import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
calculate_cart_total = target.calculate_cart_total


def test_empty_cart_returns_zero():
    assert calculate_cart_total([], 0.0825) == 0.0


def test_sum_plus_tax_single_item():
    # Spec: sum of prices plus tax. 10.00 + 10% tax = 11.00
    assert calculate_cart_total([10.0], 0.1) == 11.0


def test_sum_plus_tax_multiple_items():
    # 10.00 + 20.00 = 30.00; 30.00 * 0.0825 = 2.475 -> total 32.475 -> 32.48 (half up)
    # Accept 32.47 or 32.48 region; use a clean case instead:
    # 50.00 + 50.00 = 100.00, rate 0.5 -> 150.00
    assert calculate_cart_total([50.0, 50.0], 0.5) == 150.0


def test_zero_tax_returns_subtotal():
    assert calculate_cart_total([1.25, 2.75], 0.0) == 4.0


def test_negative_price_rejected():
    try:
        calculate_cart_total([-1.0], 0.1)
        assert False, "expected ValueError"
    except ValueError:
        pass


def test_negative_rate_rejected():
    try:
        calculate_cart_total([1.0], -0.1)
        assert False, "expected ValueError"
    except ValueError:
        pass

