import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
parse_csv_line = target.parse_csv_line


def test_simple_split():
    assert parse_csv_line("a,b,c") == ["a", "b", "c"]


def test_trims_spaces_around_fields():
    assert parse_csv_line("  a , b ,c  ") == ["a", "b", "c"]


def test_preserves_empty_middle_field():
    assert parse_csv_line("a,,c") == ["a", "", "c"]


def test_preserves_empty_leading_and_trailing_fields():
    assert parse_csv_line(",a,") == ["", "a", ""]


def test_whitespace_only_field_becomes_empty():
    assert parse_csv_line("a,   ,c") == ["a", "", "c"]


def test_single_field():
    assert parse_csv_line("hello") == ["hello"]


def test_does_not_implement_quoted_csv():
    # Spec: intentionally no quoted CSV; quotes and commas inside quotes split.
    assert parse_csv_line('a,"b,c",d') == ["a", '"b', 'c"', "d"]


def test_inner_spaces_preserved():
    assert parse_csv_line("hello world, foo bar") == ["hello world", "foo bar"]

